css:
/* === Print: oiDecommissioningAct === */
@page { margin: 20mm; }

body {
  font-family: "Times New Roman", Times, serif;
  font-size: 14pt; /* основний текст 14 */
}

/* Адресний блок: починається на відстані 2/3 від лівого краю */
.addr {
  margin-left: 66%;
  text-align: left;
  line-height: 1.35;
  white-space: pre-wrap;
  margin-bottom: 16px;
  font-family: "Times New Roman", Times, serif;
  font-size: 14pt; /* основний текст 14 */
}

/* Заголовок по центру */
.title {
  text-align: center;
  font-family: "Times New Roman", Times, serif;
  font-size: 14pt;
  margin: 6px 0;
}

/* Підзаголовок зліва, жирним */
.subtitle-left {
  text-align: left;
  font-weight: 700;
  font-family: "Times New Roman", Times, serif;
  font-size: 14pt;
  margin: 4px 0 12px;
}

/* Абзац: з відступом першого рядка, по ширині */
.p {
  text-indent: 1.25cm;
  text-align: justify;
  margin: 8px 0;
  font-family: "Times New Roman", Times, serif;
  font-size: 14pt;
}

/* Підпис «Таблиця 1…» — по правому краю */
.caption-right {
  text-align: right;
  font-weight: 600;
  margin: 10px 0 4px;
  font-family: "Times New Roman", Times, serif;
}

/* Таблиця: повна ширина, шрифт 11, шапка жирна, текст по ширині */
table.print-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11pt;             /* таблиця 11 */
  font-family: "Times New Roman", Times, serif;
}

table.print-table th,
table.print-table td {
  border: 1px solid #444;
  padding: 6px;
  vertical-align: top;
  font-family: "Times New Roman", Times, serif;
}

table.print-table th {
  font-weight: 700;            /* шапка жирним */
  text-align: center;
  font-family: "Times New Roman", Times, serif;
}

table.print-table td { text-align: justify; font-family: "Times New Roman", Times, serif;}
td.center { text-align: center !important; font-family: "Times New Roman", Times, serif;}
td.num, th.num { text-align: right !important; white-space: nowrap; font-family: "Times New Roman", Times, serif;}

/* Підписи */
.sign { margin-top: 24px; font-family: "Times New Roman", Times, serif;}

html:
{%- set items = doc.items or [] -%}

{# helper: форматування грошей #}
{%- macro money(v) -%}
  {%- if v is number -%}
    {{ "{:,.2f}".format(v).replace(",", " ").replace(".", ",") }}
  {%- else -%}-{% endif -%}
{%- endmacro -%}

{# причина зі зв’язаного рішення (якщо є) #}
{%- set basis = (doc.decision and frappe.db.get_value(
      "oiBasisDoc", doc.decision, ["reason","subject","description"], as_dict=True)) or {} -%}
{%- set basis_reason = basis.reason or basis.subject or basis.description or
      "Вихід з ладу у зв’язку з інтенсивною експлуатацією" -%}

{# Адресний блок: починається на 2/3 ширини сторінки #}
<div class="addr">
Першому
заступнику міського голови
з питань діяльності
виконавчих органів ради
Ірині РУДАКОВІЙ
</div>

{# Заголовок по центру #}
<div class="title">СЛУЖБОВА ЗАПИСКА</div>

{# Підзаголовок зліва, жирним, у два рядки #}
<div class="subtitle-left">
  Щодо списання<br/>
  матеріальних цінностей
</div>

{# Абзац: по ширині, з відступом #}
<div class="p">
  У зв’язку з інтенсивною експлуатацією та великим навантаженням прошу розглянути можливість
  списання наступних матеріальних цінностей згідно Таблиці 1.
</div>

{# «Таблиця 1...» — праворуч #}
<div class="caption-right">Таблиця 1. Список матеріальних цінностей</div>

<table class="print-table">
  <thead>
    <tr>
      <th class="center">№</th>
      <th>Найменування матеріальних цінностей</th>
      <th class="num">Ціна за одиницю</th>
      <th class="center">Кіл-ть</th>
      <th class="num">Сума, грн.</th>
      <th class="center">Інвентарний / номенклатурний номер</th>
      <th>Причина списання</th>
    </tr>
  </thead>
  <tbody>
    {%- set total_sum = 0 -%}
    {%- for i, row in enumerate(items, start=1) -%}
      {%- set a = row.asset and frappe.db.get_value(
            "oiAsset", row.asset,
            ["asset_name","inventory_no","serial_no","purchase_rate"], as_dict=True) or {} -%}
      {%- set name_display = row.asset_name or a.asset_name or row.asset or "-" -%}
      {%- set inv = row.inventory_no or a.inventory_no or "-" -%}
      {%- set unit_price = (row.unit_price if row.unit_price is not none else a.purchase_rate) -%}
      {%- set qty = row.qty or 1 -%}
      {%- set line_sum = (unit_price or 0) * qty -%}
      {%- set reason = row.writeoff_reason or basis_reason -%}
      {%- set total_sum = total_sum + line_sum -%}
      <tr>
        <td class="center">{{ i }}</td>
        <td>
          {{ name_display }}
          {%- if a.serial_no %}<br/><small>Серійний №: {{ a.serial_no }}</small>{% endif -%}
        </td>
        <td class="num">{{ money(unit_price) }}</td>
        <td class="center">{{ qty }}</td>
        <td class="num">{{ money(line_sum) }}</td>
        <td class="center">{{ inv }}</td>
        <td>{{ reason }}</td>
      </tr>
    {%- endfor -%}
    <tr>
      <td colspan="4" class="num"><b>Разом:</b></td>
      <td class="num"><b>{{ money(total_sum) }}</b></td>
      <td colspan="2"></td>
    </tr>
  </tbody>
</table>

<div class="sign">
  <div><b>В.о начальника, заступник начальника</b></div>
  <div><b>відділу інформаційних технологій</b></div>
  <div><b>та захисту інформації</b></div>
  <div><b>Максим СИСОЄВ</b></div>
</div>
